class Order {
  readonly #lines: OrderLine[] = [];
  #totalCents = 0;
  constructor(readonly id: OrderId, readonly creditLimitCents: number) {}
  addLine(line: OrderLine): void {
    if (this.#totalCents + line.amountCents > this.creditLimitCents)
      throw new CreditLimitExceeded();
    this.#lines.push(line);
    this.#totalCents += line.amountCents;
  }
  get lines(): readonly OrderLine[] { return [...this.#lines]; }
}

