type Order = Readonly<{
  id: OrderId; lines: readonly OrderLine[]; totalCents: number; limitCents: number;
}>;
const createOrder = (id: OrderId, limitCents: number): Order =>
  ({ id, lines: [], totalCents: 0, limitCents });
const addLine = (o: Order, l: OrderLine): Result<Order> =>
  o.totalCents + l.amountCents > o.limitCents
    ? err(new CreditLimitExceeded())
    : ok({ ...o, lines: [...o.lines, l], totalCents: o.totalCents + l.amountCents });
